package main
import("encoding/json";"fmt";"os";"path/filepath";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz")
func must(e error){if e!=nil{panic(e)}}
func main(){source,e:=os.ReadFile(os.Args[1]);must(e);for _,name:=range []string{"short-reuse","long-atoms","nested-mixed","fresh-dominant"}{b,e:=os.ReadFile(filepath.Join(os.Args[2],name+".json"));must(e);var w hir.MemoryHostWorkload;must(json.Unmarshal(b,&w));m,e:=nanz.Parse(string(source),os.Args[1]);must(e);m.Target=hir.TargetCPM;run,e:=hir.RunMemoryHostLoopProfile(m,w);must(e);if run.CompletedCalls!=uint64(len(w.Calls))||run.FailedCalls!=0{panic("incomplete")};for i,s:=range run.Sites.Sites{if s.Function=="region_match"||s.Function=="intern_region"{fmt.Printf("%s %s %s entries%d body%d\n",name,s.Function,s.HIRPath,run.Counts[i].Entries,run.Counts[i].BodyEntries)}};encoded,e:=json.MarshalIndent(run,"","  ");must(e);must(os.WriteFile(filepath.Join(os.Args[3],name+"-raw-profile.json"),encoded,0644))}}
